#!/usr/bin/env node
// Compares the PDFs generated by the tests (e2e/output/pdfs) with the committed reference PDFs
// (e2e/reference-pdfs). Pages are rendered to images, changed pixels are marked red.
//
//   devert-compare-pdfs            writes e2e/output/compare/index.html and report.png
//   devert-compare-pdfs --update   copies the generated PDFs over the references
// Paths (relative to the plugin root) can be changed with --reference, --generated and --out.
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
import { createServer } from 'node:http';
import { chromium } from '@playwright/test';
import pixelmatch from 'pixelmatch';
import { PNG } from 'pngjs';

const arg = (name, fallback) => {
  const i = process.argv.indexOf(`--${name}`);
  return path.resolve(process.cwd(), i > -1 ? process.argv[i + 1] : fallback);
};
const referenceDir = arg('reference', 'e2e/reference-pdfs');
const newDir = arg('generated', 'e2e/output/pdfs');
const outDir = arg('out', 'e2e/output/compare');
const SCALE = 1.3;

const listPdfs = (dir) => (existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.pdf')).sort() : []);

mkdirSync(referenceDir, { recursive: true });
if (process.argv.includes('--update')) {
  for (const file of listPdfs(newDir)) copyFileSync(path.join(newDir, file), path.join(referenceDir, file));
  console.log(`Updated ${listPdfs(newDir).length} reference PDFs`);
  process.exit(0);
}

// pdf.js runs in Chromium (the browser Playwright already provides), so no native canvas is needed.
const pdfjsDir = path.join(path.dirname(createRequire(import.meta.url).resolve('pdfjs-dist/package.json')), 'build');
const servedDirs = { '/pdfjs/': pdfjsDir, '/old/': referenceDir, '/new/': newDir };
const mimeTypes = { '.mjs': 'text/javascript', '.js': 'text/javascript', '.pdf': 'application/pdf' };

const server = createServer((req, res) => {
  const url = decodeURIComponent(req.url.split('?')[0]);
  const prefix = Object.keys(servedDirs).find((p) => url.startsWith(p));
  const file = prefix && path.join(servedDirs[prefix], path.basename(url));
  if (!file || !existsSync(file)) {
    res.writeHead(url === '/' ? 200 : 404, { 'content-type': 'text/html' }).end(url === '/' ? '<!doctype html>' : '');
    return;
  }
  res.writeHead(200, { 'content-type': mimeTypes[path.extname(file)] ?? 'application/octet-stream' }).end(readFileSync(file));
});
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const browser = await chromium.launch();
const browserPage = await browser.newPage();
await browserPage.goto(`http://127.0.0.1:${server.address().port}/`);

async function renderPages(url) {
  const dataUrls = await browserPage.evaluate(
    async ({ url, scale }) => {
      const pdfjs = await import('/pdfjs/pdf.mjs');
      pdfjs.GlobalWorkerOptions.workerSrc = '/pdfjs/pdf.worker.mjs';
      const pdf = await pdfjs.getDocument(url).promise;
      const images = [];
      for (let n = 1; n <= pdf.numPages; n++) {
        const page = await pdf.getPage(n);
        const viewport = page.getViewport({ scale });
        const canvas = document.createElement('canvas');
        canvas.width = Math.ceil(viewport.width);
        canvas.height = Math.ceil(viewport.height);
        const context = canvas.getContext('2d');
        context.fillStyle = '#fff';
        context.fillRect(0, 0, canvas.width, canvas.height);
        await page.render({ canvasContext: context, viewport }).promise;
        images.push(canvas.toDataURL('image/png'));
      }
      return images;
    },
    { url, scale: SCALE },
  );
  return dataUrls.map((d) => PNG.sync.read(Buffer.from(d.split(',')[1], 'base64')));
}

/** Copies an image onto a white canvas of the given size so that differently sized pages can be compared. */
function pad(png, width, height) {
  const out = new PNG({ width, height });
  out.data.fill(255);
  PNG.bitblt(png, out, 0, 0, png.width, png.height, 0, 0);
  return out;
}

const save = (name, png) => writeFileSync(path.join(outDir, name), PNG.sync.write(png));
const escapeHtml = (s) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

mkdirSync(path.join(outDir, 'old'), { recursive: true });
mkdirSync(path.join(outDir, 'new'), { recursive: true });

const names = [...new Set([...listPdfs(referenceDir), ...listPdfs(newDir)])].sort();
const results = [];

for (const file of names) {
  const base = file.replace(/\.pdf$/, '');
  const oldFile = path.join(referenceDir, file);
  const newFile = path.join(newDir, file);
  const result = { base, pages: [], status: 'ok' };
  if (!existsSync(oldFile)) result.status = 'no reference';
  else if (!existsSync(newFile)) result.status = 'not generated';
  else {
    copyFileSync(oldFile, path.join(outDir, 'old', file));
    copyFileSync(newFile, path.join(outDir, 'new', file));
    const [oldPages, newPages] = [await renderPages(`/old/${file}`), await renderPages(`/new/${file}`)];
    for (let i = 0; i < Math.max(oldPages.length, newPages.length); i++) {
      const width = Math.max(oldPages[i]?.width ?? 0, newPages[i]?.width ?? 0);
      const height = Math.max(oldPages[i]?.height ?? 0, newPages[i]?.height ?? 0);
      const a = pad(oldPages[i] ?? new PNG({ width: 1, height: 1 }), width, height);
      const b = pad(newPages[i] ?? new PNG({ width: 1, height: 1 }), width, height);
      const diff = new PNG({ width, height });
      const changed = pixelmatch(a.data, b.data, diff.data, width, height, {
        threshold: 0.1,
        diffColor: [255, 0, 0],
        alpha: 0.4,
      });
      const prefix = `${base}-p${i + 1}`;
      save(`${prefix}-old.png`, a);
      save(`${prefix}-new.png`, b);
      save(`${prefix}-diff.png`, diff);
      result.pages.push({ prefix, changed, percent: (changed / (width * height)) * 100, missing: !oldPages[i] ? 'old' : !newPages[i] ? 'new' : '' });
    }
    if (result.pages.some((p) => p.changed > 0)) result.status = 'changed';
  }
  results.push(result);
}

const badge = { ok: '#2e7d32', changed: '#c62828', 'no reference': '#ef6c00', 'not generated': '#c62828' };
const html = `<!doctype html><meta charset="utf-8"><title>PDF comparison</title>
<style>
body{font:14px system-ui,sans-serif;margin:24px;background:#fafafa;color:#222}
h2{margin:32px 0 4px}.badge{color:#fff;border-radius:4px;padding:2px 8px;font-size:12px}
.row{display:flex;gap:12px;margin:8px 0 24px;align-items:flex-start}.row figure{margin:0;flex:1}
.row img{width:100%;border:1px solid #ccc;background:#fff}figcaption{font-weight:600;margin-bottom:4px}
nav a{margin-right:12px}
</style>
<h1>PDF comparison: reference (old) vs. generated (new)</h1>
<p>Changed pixels are red in the third column. Dates, IDs and product names change on every run.</p>
<nav>${results.map((r) => `<a href="#${r.base}">${r.base}</a>`).join('')}</nav>
${results
  .map(
    (r) => `<h2 id="${r.base}">${escapeHtml(r.base)}.pdf <span class="badge" style="background:${badge[r.status]}">${r.status}</span></h2>
<a href="old/${r.base}.pdf">old.pdf</a> · <a href="new/${r.base}.pdf">new.pdf</a>
${r.pages
  .map(
    (p) => `<p>Page ${p.prefix.split('-p').pop()}: ${p.changed} pixels changed (${p.percent.toFixed(2)} %)${p.missing ? ` – page missing in ${p.missing}` : ''}</p>
<div class="row"><figure><figcaption>old</figcaption><img src="${p.prefix}-old.png"></figure><figure><figcaption>new</figcaption><img src="${p.prefix}-new.png"></figure><figure><figcaption>diff</figcaption><img src="${p.prefix}-diff.png"></figure></div>`,
  )
  .join('')}`,
  )
  .join('')}`;
writeFileSync(path.join(outDir, 'index.html'), html);

// the same report as one image, to look at it without downloading an archive (e.g. on a phone)
const reportPage = await browser.newPage({ viewport: { width: 1200, height: 900 } });
await reportPage.goto(pathToFileURL(path.join(outDir, 'index.html')).href);
await reportPage.screenshot({ path: path.join(outDir, 'report.png'), fullPage: true });
await browser.close();
server.close();

for (const r of results) {
  const changed = r.pages.reduce((sum, p) => sum + p.changed, 0);
  console.log(`${r.status.padEnd(14)} ${r.base}${r.pages.length ? ` (${r.pages.length} page(s), ${changed} px changed)` : ''}`);
}
console.log(`Report: ${path.join(outDir, 'index.html')} (image: report.png)`);
